static std::filesystem::path source,root,cas;static std::string model,nonce;static int trial,ci;static size_t frameat,guardat;static std::set<std::string>seen;static std::vector<double>prefix,out;static std::vector<std::vector<int64_t>>gold;static std::vector<double>bounds;static std::ofstream ledger,guards;static double rounderror;
static void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
template<class F>void safe(F f){try{f();}catch(const std::exception&e){fprintf(stderr,"TPACF_OBSERVER %s\n",e.what());fflush(stderr);std::abort();}}
static std::string digest(const void*p,size_t n){unsigned char b[32];SHA256((const unsigned char*)p,n,b);std::ostringstream s;for(auto c:b)s<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(c);return s.str();}
static std::string keep(const unsigned char*p,size_t n){auto h=digest(p,n);auto dest=cas/(h+".bin.gz");if(!std::filesystem::exists(dest)){auto tmp=dest.string()+".tmp"+std::to_string(getpid());auto z=gzopen(tmp.c_str(),"wb1");need(z,"CAScreate");need(gzwrite(z,p,n)==int(n),"CASwrite");need(gzclose(z)==Z_OK,"CASclose");std::filesystem::rename(tmp,dest);}return h;}
static std::vector<int64_t>readgold(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary|std::ios::ate);need(bool(f),"oracleopen");auto n=f.tellg();need(n%8==0,"oraclebytes");std::vector<int64_t>v(size_t(n)/8);f.seekg(0);f.read((char*)v.data(),n);need(bool(f),"oracleread");return v;}
extern "C" void tp_start(const char*m,const char*s,const char*r){safe([&](){model=m;source=s;root=std::filesystem::path(r)/model;cas=std::filesystem::path(r)/"CAS";std::filesystem::create_directories(root);std::filesystem::create_directories(cas);nonce=std::to_string(std::chrono::system_clock::now().time_since_epoch().count())+"_"+std::to_string(getpid());std::ifstream f(source/"data/source_boundaries63.bin",std::ios::binary);bounds.resize(63);f.read((char*)bounds.data(),504);need(bool(f),"boundariesread");for(int k=0;k<3;k++)gold.push_back(readgold(source/"data"/("case"+std::to_string(k)+"_oracle.bin")));});}
extern "C" void tp_begin(int t){safe([&](){trial=t;ci=-1;prefix.clear();out.clear();rounderror=0;if(ledger.is_open())ledger.close();if(guards.is_open())guards.close();auto stem=nonce+"_trial"+std::to_string(t);ledger.open(root/(stem+".inputs.jsonl"));guards.open(root/(stem+".guards.bin"),std::ios::binary);need(bool(ledger)&&bool(guards),"sidecaropen");printf("TPACF_CAPTURE model=%s trial=%d inputs=%s guards=%s\n",model.c_str(),t,(root/(stem+".inputs.jsonl")).c_str(),(root/(stem+".guards.bin")).c_str());fflush(stdout);});}
extern "C" void tp_case(int index,int n,int nr,int njk,const int*jk,int zero,const double*b){safe([&](){need(index==ci+1,"caseorder");ci=index;const auto&c=CASES[ci];need(n==c.n&&nr==c.nr&&njk==c.njk&&zero==29,"actualcaseparams");need(memcmp(jk,c.jk.data(),njk*4)==0,"actualJKsizes");need(memcmp(b,bounds.data(),504)==0,"actualGPUconstant63bits");frameat=guardat=0;seen.clear();for(double x:{double(n),double(nr),double(njk),64.,double(zero),5.,1.,10000.,1.})prefix.push_back(x);for(int k=0;k<njk;k++)prefix.push_back(jk[k]);prefix.insert(prefix.end(),b,b+63);auto h=keep((const unsigned char*)b,504);ledger<<"{\"case\":"<<ci<<",\"kind\":\"actual_GPUconstant63\",\"sha256\":\""<<h<<"\",\"bytes\":504}\n";});}
extern "C" void tp_input(const unsigned char*p,size_t n){safe([&](){const auto&c=CASES[ci];need(n==16384*8,"actualuploadbytes");auto h=keep(p,n);need(frameat<c.seq.size()&&h==c.seq[frameat],"actualH2Dframeorderbits");ledger<<"{\"case\":"<<ci<<",\"frame\":"<<frameat<<",\"sha256\":\""<<h<<"\",\"bytes\":"<<n<<"}\n";frameat++;if(seen.insert(h).second){std::vector<double>d(n/8);memcpy(d.data(),p,n);prefix.insert(prefix.end(),d.begin(),d.end());}});}
extern "C" void tp_guard(int id,const unsigned char*p){safe([&](){need(id==int(guardat),"actualguardbufferorder");int32_t h[]={ci,id,512};guards.write((char*)h,12);guards.write((const char*)p,512);for(int k=0;k<512;k++)need(p[k]==0xa5,"actualguardbytes");need(bool(guards),"guardwrite");guardat++;});}
static std::vector<double>report(const std::filesystem::path&p,const int64_t*v,int j,int nr){std::ifstream f(p);need(bool(f),"source_report_open");std::string line;std::getline(f,line);std::vector<double>encoded;const auto DD=v;const auto DR=v+(j+1)*64;const auto RR=DR+(j+1)*64;int rows=0;
while(std::getline(f,line)){if(line.empty())continue;std::istringstream s(line);std::vector<std::string>tokens;std::string t;while(s>>t)tokens.push_back(t);int row=rows++;bool first=row==0,last=row==21;need(row<=21,"reportrows");need(tokens.size()==size_t(first?5:last?4:1+4*(j+1)),"reportcolumns");double angle=std::stod(tokens[0].substr((first||last)?1:0));double expected=pow(10.,(first?0:last?20:row)/5.);need(std::abs(angle-expected)<=5.0001e-7,"reportedangularlabelrounding");
auto integer=[&](int pos,int64_t want){need(std::stoll(tokens[pos])==want,"actualreportcount");};if(first||last){int bin=first?0:21;integer(1,DD[bin]);integer(2,DR[bin]);integer(3,RR[bin]);if(first)need(tokens[4]=="-","underflowwabsent");}else for(int l=0;l<=j;l++){int pos=1+4*l,bin=10+row;integer(pos,DD[l*64+bin]);integer(pos+1,DR[l*64+bin]);integer(pos+2,RR[bin]);if(RR[bin]){need(tokens[pos+3]!="-","actualreportwvalid");double want=(nr*double(DD[l*64+bin])-double(DR[l*64+bin]))/double(RR[bin])+1.;double error=std::abs(std::stod(tokens[pos+3])-want);rounderror=std::max(rounderror,error);need(error<=5.0001e-7+1e-14*std::abs(want),"actualsource6decimalwformula");}else need(tokens[pos+3]=="-","actualreportmissingw");}
for(auto& token:tokens){double kind=0,val=0;if(token=="-")kind=2;else if(token[0]=='<'||token[0]=='>'){kind=token[0]=='<'?-1:1;val=std::stod(token.substr(1));}else val=std::stod(token);need(std::isfinite(val),"reportedfinitevalue");encoded.push_back(kind);encoded.push_back(val);}}
need(rows==22,"fullreportedrows");return encoded;}
extern "C" void tp_output(const int64_t*raw,const int64_t*compiled,const char*path){safe([&](){const auto&c=CASES[ci];int j=c.njk,nr=c.nr;auto&g=gold[ci];need(frameat==c.seq.size()&&guardat==8,"allactualinputsandguards");need(memcmp(raw,g.data(),g.size()*8)==0,"fullindependentphysicalcounts_sourceJKsentinelpolicy");size_t compiled_n=(2*(j+1)+1)*64;std::vector<int64_t>want(compiled_n,0);auto dd=want.data(),dr=dd+(j+1)*64,rr=dr+(j+1)*64;auto GDD=g.data(),GDR=GDD+j*64,GRR=GDR+nr*j*64;
for(int bin=0;bin<64;bin++){for(int k=0;k<j;k++)dd[bin]+=GDD[k*64+bin];for(int r=0;r<nr;r++){rr[bin]+=GRR[r*64+bin];for(int k=0;k<j;k++)dr[bin]+=GDR[(r*j+k)*64+bin];}for(int k=1;k<=j;k++){dd[k*64+bin]=dd[bin]-GDD[(k-1)*64+bin];dr[k*64+bin]=dr[bin];for(int r=0;r<nr;r++)dr[k*64+bin]-=GDR[(r*j+k-1)*64+bin];}}
need(memcmp(compiled,want.data(),compiled_n*8)==0,"sourcecompiledone-sidedreportpolicy");auto tokens=report(path,compiled,j,nr);for(double x:{double(ci),double(g.size()),double(compiled_n),double(tokens.size())})out.push_back(x);for(size_t k=0;k<g.size();k++)out.push_back(raw[k]);for(size_t k=0;k<compiled_n;k++)out.push_back(compiled[k]);out.insert(out.end(),tokens.begin(),tokens.end());printf("TPACF_CASE trial=%d case=%d n=%d nr=%d njk=%d inputframes=%zu rawhist=%zu reportfields=%zu\n",trial,ci,c.n,nr,j,frameat,g.size(),tokens.size());});}
extern "C" void tp_write(int t,double seconds){safe([&](){need(t==trial&&ci==2,"trialcasecoverage");need(prefix.size()==PREFIX_VALUES,"actualprefixcount");need(prefix.size()+out.size()==TOTAL_VALUES,"completeprimarycount");prefix.insert(prefix.end(),out.begin(),out.end());std::string name="trial"+std::to_string(t)+".bin";std::ofstream f(name,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*8);f.close();need(bool(f),"primarywrite");ledger.flush();guards.flush();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"max_source_report_rounding_error\":%.17g,\"jit_excluded\":true,\"timing_region\":\"sum3case_source_tiled_ACF_histogram_transfer_hostaccumulation_observerpaused\",\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",t,seconds,prefix.size(),rounderror,name.c_str(),prefix.size());fflush(stdout);});}
extern "C" void tp_finish(){safe([](){ledger.close();guards.close();});}
